package com.example.spring_blog.user;import jakarta.persistence.*;import lombok.Builder;import lombok.Getter;import lombok.NoArgsConstructor;//복합 유니크 제약//한 사용자는 같은 역할을 한 번만 가진다.// (1, admin) (1, User) (2, User)@NoArgsConstructor@Getter@Entity@Table(name = "user_role_tb", uniqueConstraints = {@UniqueConstraint(name = "uk_user_role", columnNames = {"user_id", "role"})})public class UserRole {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    //    enum을 숫자가 아닌 문자열로 저장    @Enumerated(EnumType.STRING)    @Column(nullable = false, length = 20)    private Role role;    @Builder    public UserRole(Role role) {        this.role = role;    }}